import { Component, input, signal } from '@angular/core';

@Component({
  selector: 'app-expander',
  template: `
    <button (click)="open.set(!open())">{{ label() }}</button>
    @if (open()) {
      <!-- Hides the content; it was created with the parent -->
      <ng-content />
    }
  `,
})
export class Expander {
  readonly label = input.required<string>();
  readonly open = signal(false);
}

import { NgTemplateOutlet } from '@angular/common';
import {
  Component, TemplateRef, contentChild, input, signal,
} from '@angular/core';

@Component({
  selector: 'app-expander',
  imports: [NgTemplateOutlet],
  template: `
    <button (click)="open.set(!open())">{{ label() }}</button>
    @if (open()) {
      <ng-container [ngTemplateOutlet]="body()" />
    }
  `,
})
export class Expander {
  readonly label = input.required<string>();
  readonly open = signal(false);
  // The caller's <ng-template>: rendered on open, destroyed on close
  readonly body = contentChild(TemplateRef);
}
